#include "au3-effects/StatefulEffect.h"

class WaveChannel;

class BUILTIN_EFFECTS_API Repair : public StatefulEffect
{
public:
    static const ComponentInterfaceSymbol Symbol;

    // ComponentInterface implementation

    ComponentInterfaceSymbol GetSymbol() const override;
    TranslatableString GetDescription() const override;

    // EffectDefinitionInterface implementation

    EffectType GetType() const override;
    EffectGroup GetGroup() const override { return EffectGroup::NoiseRemovalAndRepair; }
    bool IsInteractive() const override;
    bool ParamsAreInputAgnostic() const override { return false; }

    // Effect implementation

    bool Process(EffectInstance& instance, EffectSettings& settings) override;

    bool NeedsDither() const override;

private:
    // EffectRepair implementation

    bool ProcessOne(
        int count, WaveChannel& track, sampleCount start, size_t len, size_t repairStart, // offset relative to start
        size_t repairLen);
};
