// Same as an13 but gate every frame whose window intersects [clickStart,clickEnd) (the actual transient support),
// and zero the full frequency box. Then measure residual.
#include "/home/dev/feedback/uid24898/src/effects/builtin_collection/spectralrepair/spectralrepair.h"
#include <cstdio>
#include <vector>
#include <cmath>
using namespace au::effects;
static float magAt(std::vector<float>&sig,size_t N,size_t frame,size_t bin){
    size_t hop=N/2, fs=frame*hop; std::vector<float> re(N),im(N),w(N);
    for(size_t i=0;i<N;++i){w[i]=.5*(1-std::cos(2*M_PI*i/(N-1))); re[i]=fs+i<sig.size()?sig[fs+i]*w[i]:0;}
    SpectralRepair::Fft(re,im,false); return std::hypot(re[bin],im[bin]);
}
int main(){
    const double rate=44100; const size_t n=44100,N=2048,hop=N/2;
    std::vector<float> x(n,0); size_t cc=22050, c0=cc-256,c1=cc+256;
    for(size_t i=c0;i<c1;++i){double e=std::sin(M_PI*(i-c0)/512.0);x[i]=.8*e*std::sin(2*M_PI*4500*(i/rate));}
    double binHz=rate/N; size_t lo=std::round(2000/binHz),hi=std::round(9000/binHz);
    size_t frameCount=n/hop+1;
    std::vector<float> w(N); for(size_t i=0;i<N;++i)w[i]=.5*(1-std::cos(2*M_PI*i/(N-1)));
    std::vector<std::vector<float>> R(frameCount,std::vector<float>(N)),I(frameCount,std::vector<float>(N));
    std::vector<float> re(N),im(N);
    for(size_t f=0;f<frameCount;++f){size_t fs=f*hop;
        for(size_t i=0;i<N;++i){re[i]=fs+i<n?x[fs+i]*w[i]:0;im[i]=0;}
        SpectralRepair::Fft(re,im,false);R[f]=re;I[f]=im;}
    // every frame whose window [fs,fs+N) intersects the transient support [c0,c1)
    size_t flo=c0>=N?(c0-N)/hop+1:0, fhi=std::min(frameCount-1,(c1-1)/hop);
    printf("gating frames %zu..%zu\n",flo,fhi);
    for(size_t f=flo;f<=fhi;++f)for(size_t b=lo;b<=hi;++b){R[f][b]=0;I[f][b]=0;}
    std::vector<float> out(n,0),norm(n,0);
    for(size_t f=0;f<frameCount;++f){size_t fs=f*hop;re=R[f];im=I[f];SpectralRepair::Fft(re,im,true);
        for(size_t i=0;i<N && fs+i<n;++i){out[fs+i]+=re[i]*w[i];norm[fs+i]+=w[i]*w[i];}}
    for(size_t i=0;i<n;++i)if(norm[i]>1e-12)out[i]/=norm[i];
    printf("re-analysed bin213 f20=%.3f f21=%.3f\n",magAt(out,N,20,213),magAt(out,N,21,213));
    double peak=0; for(size_t i=c0;i<c1;++i)peak=std::max(peak,double(std::abs(out[i])));
    printf("residual peak in transient support: %.4f\n",peak);
}
EOF
