// Direct time-domain measurement of OLA output, no re-analysis.
#include "/home/dev/feedback/uid24898/src/effects/builtin_collection/spectralrepair/spectralrepair.h"
#include <cstdio>
#include <vector>
#include <cmath>
using namespace au::effects;
static double rms(std::vector<float>&x,size_t a,size_t b){double s=0;for(size_t i=a;i<b;++i)s+=x[i]*x[i];return sqrt(s/(b-a));}
int main(){
    const double rate=44100; const size_t n=44100,N=2048,hop=N/2;
