    for(size_t i=c0;i<c1;++i){double e=std::sin(M_PI*(i-c0)/512.0);x[i]=.8*e*std::sin(2*M_PI*4500*(i/rate));}
    double inRms=rms(x,c0,c1);
    double binHz=rate/N;
    SpectralRepairRegion r; r.startSample=c0;r.endSample=c1;r.lowHz=2000;r.highHz=9000;
    for(int exp : {0,1,2,3}){
        SpectralRepairSettings st; st.toleranceFrames=exp; st.toleranceBins=exp;
        auto y=x; SpectralRepair::Process(y,rate,r,st);
        double peak=0; for(size_t i=c0;i<c1;++i)peak=std::max(peak,double(std::abs(y[i])));
        printf("tol=%d inputRMS=%.4f outputRMS=%.4f reduction=%.2fdB residualPeak=%.4f\n",
            exp,inRms,rms(y,c0,c1),20*log10(inRms/rms(y,c0,c1)),peak);
    }
}
