#include <cstdio>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;
int main(){
    // emulate texture median when neighbourhood is silence (magnitudes ~0)
    vector<float> v(24, 1e-9f);
    sort(v.begin(),v.end());
    float tex=v[v.size()/2];
    float orig=30.0f;
    float excess=20*log10f(orig/tex);
    printf("tex=%g excess=%g isfinite=%d\n",tex,excess,isfinite(excess));
    float gate=6.0f, t=excess>=gate?1.0f:excess/gate;
    float targetDb=20*log10f(tex)+(1-t)*excess;
    float recon=powf(10,targetDb/20);
    printf("t=%g targetDb=%g recon=%g\n",t,targetDb,recon);
