+        for (size_t bin = lowBin; bin <= highBin; ++bin) {
+            const double magnitude = std::hypot(re[bin], im[bin]);
+            power += magnitude * magnitude;
+        }
+        ++frameCount;
+    }
+    return std::sqrt(power / static_cast<double>(frameCount * (highBin - lowBin + 1)));
