    for (size_t len = 2; len <= n; len <<= 1) {
        const float angle = sign * 2.0f * kPi / static_cast<float>(len);
        const float wReal = std::cos(angle);
        const float wImag = std::sin(angle);
        const size_t half = len >> 1;
